/*
 * A106592  Irregular triangle read by rows generated by the morphism 1->456,
 *          2->44, 3->55, 4->22, 5->33, 6->123 starting from a(0)=1.
 * https://oeis.org/A106592
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   not stated
 * Range:     u8 n <= 8177, u16 n <= 8177, u32 n <= 8177, u64 n <= 8177,
 *            u128 n <= 8177, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Irregular triangle read by rows generated by the morphism
   1→456, 2→44, 3→55, 4→22, 5→33, 6→123, starting from a(0)=1.
   Each a(n) is the nth element of the concatenated rows. */

#include <stdlib.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    /* cache of already produced sequence terms */
    static seq_t *cache   = NULL;
    static idx_t   c_len  = 0;
    static idx_t   c_cap  = 0;

    /* current row ready to be appended */
    static seq_t *row      = NULL;
    static idx_t   r_len   = 0;
    static idx_t   r_cap   = 0;
    /* index of the next element to take from the current row */
    static idx_t   r_pos   = 0;

    /* one‑time initialization */
    if (!cache) {
        /* start with the symbol '1' */
        r_cap = 1;
        r_len = 1;
        row   = (seq_t *)malloc(sizeof(seq_t) * r_cap);
        row[0] = (seq_t)1;
        /* cache is empty initially */
        c_cap = 16;
        cache = (seq_t *)malloc(sizeof(seq_t) * c_cap);
    }

    /* generate terms until `n` is reachable */
    while (c_len <= n) {
        /* append as many elements of the current row as needed */
        while (r_pos < r_len && c_len <= n) {
            if (c_cap <= c_len) {
                idx_t new_cap = c_cap ? c_cap * 2 : 16;
                if (new_cap <= c_len) new_cap = c_len + 1;
                seq_t *tmp = (seq_t *)realloc(cache, sizeof(seq_t) * new_cap);
                cache = tmp;
                c_cap = new_cap;
            }
            cache[c_len++] = row[r_pos++];
        }

        if (c_len > n) break;        /* requested value produced */

        /* all symbols of the current row were consumed; generate next row */
        idx_t next_len = 0;
        /* maximum possible length is 3 * r_len, allocate conservatively */
        idx_t alloc_cap = r_len * 3 + 2;
        seq_t *next_row = (seq_t *)malloc(sizeof(seq_t) * alloc_cap);

        for (idx_t i = 0; i < r_len; ++i) {
            unsigned v = (unsigned)row[i];   /* values are 1 … 6 */
            switch (v) {
                case 1: next_row[next_len++] = (seq_t)4;
                        next_row[next_len++] = (seq_t)5;
                        next_row[next_len++] = (seq_t)6; break;
                case 2: next_row[next_len++] = (seq_t)4;
                        next_row[next_len++] = (seq_t)4; break;
                case 3: next_row[next_len++] = (seq_t)5;
                        next_row[next_len++] = (seq_t)5; break;
                case 4: next_row[next_len++] = (seq_t)2;
                        next_row[next_len++] = (seq_t)2; break;
                case 5: next_row[next_len++] = (seq_t)3;
                        next_row[next_len++] = (seq_t)3; break;
                case 6: next_row[next_len++] = (seq_t)1;
                        next_row[next_len++] = (seq_t)2;
                        next_row[next_len++] = (seq_t)3; break;
            }
        }

        free(row);
        row   = next_row;
        r_len = next_len;
        r_cap = alloc_cap;
        r_pos = 0;                 /* start at beginning of new row */
    }

    return cache[(size_t)n];
}
